// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    Recorder rec;

    function setUp() public { c = new airdrop(); rec = new Recorder(); }

    // fuzz: from address (actor), single-element or multi-element _tos array length and values
    function testFuzz_property(address from, uint8 len, address a1, address a2, uint256 v) public {
        // keep len small but allow 1 or 2+ to expose difference
        uint256 _len = bound(len, 1, 2); // 1 or 2 recipients

        // build _tos array from fuzzed addresses
        address[] memory tos = new address[](_len);
        tos[0] = a1 == address(0) ? address(1) : a1; // avoid zero address making calls ambiguous
        if (_len > 1) tos[1] = a2 == address(0) ? address(2) : a2;

        // ensure c will call the external counterparty we control: pass rec's address as caddress
        address caddress = address(rec);

        // Call transfer and record whether it returns (non-revert)
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool ret) { ok = ret; } catch { ok = false; }

        // The reference implementation MUST have invoked transferFrom exactly _len times and recorded them.
        // Recorder.recordCount() exposes how many calls it observed; this is the observable behavior of c.
        uint256 recorded = rec.recordCount();

        // General rule: for any non-empty tos, reference calls transferFrom exactly tos.length times -> recorded == tos.length
        // Mutant that starts loop at 1 will make recorded == tos.length - 1 when tos.length >=1 (specifically when tos.length==1 it makes 0 calls).
        // Assert the property (this holds for the reference for ALL inputs; mutant will fail for some inputs)
        assertTrue(recorded == _len);
    }
}

// Recorder implements the exact selector the contract C encodes: transferFrom(address,address,uint256)
contract Recorder {
    // store number of calls and details
    uint256 public calls;
    address[] public froms;
    address[] public tos;
    uint256[] public vals;

    // function matching the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        froms.push(from);
        tos.push(to);
        vals.push(v);
        return true;
    }

    function recordCount() external view returns (uint256) {
        return calls;
    }
}
